'use strict';
/**
 * lib/quick-badge.js — 通过标准 Chromium CDP (--remote-debugging-port=9222)
 * 在 AWS Quick 桌面客户端内每条 AI 回复下方优雅展示实际底层模型（如 Generated by Opus 5.5 · smart）
 *
 * 特点：
 *  - 零修改 AWS Quick 安装包 / app.asar，不破坏签名与自动更新
 *  - 仅在用户开启开关并带 --remote-debugging-port=9222 启动 Quick 时自动附着
 *  - 实时监听 WebSocket turn_usage 帧 + 自动回填本地已同步对话的模型元数据
 */

const http = require('http');

const CDP_PORT = Number(process.env.QWM_CDP_PORT || 9222);

let state = {
  port: CDP_PORT,
  reachable: false,
  attached: false,
  targetTitle: '',
  targetUrl: '',
  lastAttachAt: null,
  lastError: null,
  lastInspect: null,
};

function getJson(url, timeoutMs = 2000) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, { timeout: timeoutMs }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (c) => { body += c; });
      res.on('end', () => {
        try { resolve(JSON.parse(body)); }
        catch (e) { reject(new Error(body.slice(0, 120) || 'bad_json')); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    req.on('error', reject);
  });
}

async function findPageTarget(port = CDP_PORT) {
  const list = await getJson(`http://127.0.0.1:${port}/json/list`, 2000);
  if (!Array.isArray(list) || !list.length) return null;
  const pages = list.filter((t) => t && t.type === 'page' && t.webSocketDebuggerUrl);
  return pages.find((t) => /quick|index\.html/i.test((t.title || '') + ' ' + (t.url || '')))
    || pages[0]
    || null;
}

async function evalInPage(wsUrl, expression, timeoutMs = 8000) {
  const ws = new WebSocket(wsUrl);
  return new Promise((resolve, reject) => {
    let settled = false;
    const finish = (err, val) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { ws.close(); } catch (_) {}
      if (err) reject(err);
      else resolve(val);
    };
    const timer = setTimeout(() => finish(new Error('cdp_eval_timeout')), timeoutMs);

    ws.addEventListener('error', (e) => finish(new Error((e && e.message) || 'ws_error')));
    ws.addEventListener('open', () => {
      ws.send(JSON.stringify({
        id: 1,
        method: 'Runtime.evaluate',
        params: {
          expression,
          awaitPromise: true,
          returnByValue: true,
          allowUnsafeEvalBlockedByCSP: true,
        },
      }));
    });
    ws.addEventListener('message', (ev) => {
      try {
        const msg = JSON.parse(typeof ev.data === 'string' ? ev.data : ev.data.toString());
        if (msg.id !== 1) return;
        const r = msg.result || {};
        if (r.exceptionDetails) {
          return finish(new Error((r.exceptionDetails.exception && r.exceptionDetails.exception.description) || r.exceptionDetails.text || 'eval_exception'));
        }
        finish(null, r.result ? r.result.value : undefined);
      } catch (e) {
        finish(e);
      }
    });
  });
}

// 注入到 AWS Quick 渲染页面的极简模型与思考强度标注脚本（幂等、热升级）
const BADGE_SCRIPT = `(() => {
  const VER = 7;
  if ((window.__qmBadgeVer || 0) >= VER && window.__qmBadgeActive) {
    return { ok: true, status: 'already_attached', ver: window.__qmBadgeVer, liveCount: (window.__qmUsageLog || []).length };
  }
  window.__qmBadgeVer = VER;
  window.__qmBadgeActive = true;
  window.__qmUsageLog = window.__qmUsageLog || [];
  window.__qmUsageByText = window.__qmUsageByText || Object.create(null);
  window.__qmLastSentEffort = window.__qmLastSentEffort || '';
  window.__qmTurnDidThink = false;
  window.__qmLastTurnUsage = null;
  delete window.__qmRawFrames;
  delete window.__qmRawOut;

  const fmtModel = (id) => {
    const s = String(id || '').trim();
    if (!s) return '';
    const m = s.match(/claude-(opus|sonnet|haiku)-([0-9]+)[.-]([0-9]+)/i);
    if (m) return m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase() + ' ' + m[2] + '.' + m[3];
    return s.replace(/^(?:us|eu|ap|global)\\.(?:anthropic|amazon)\\./i, '').replace(/^anthropic\\./i, '');
  };

  const fmtTier = (tier) => {
    const t = String(tier || '').trim().toLowerCase();
    if (!t) return '';
    const map = { smart: 'Smart', balanced: 'Balanced', fast: 'Fast', advanced: 'Advanced' };
    return map[t] || t;
  };

  const readThinkingEffort = (tier) => {
    try {
      const raw = localStorage.getItem('quickwork-settings');
      if (!raw) return '';
      const st = (JSON.parse(raw) || {}).state || {};
      if (st.thinkingEnabled === false) return 'off';
      const tKey = String(tier || st.agentMode || '').toLowerCase();
      const perMode = st.modeEffortLevel && tKey ? st.modeEffortLevel[tKey] : '';
      return String(perMode || st.thinkingEffortLevel || st.thinkingEffort || '').trim().toLowerCase();
    } catch (_) {
      return '';
    }
  };

  const fmtEffort = (effort) => {
    const e = String(effort || '').trim().toLowerCase();
    if (!e) return '';
    const map = {
      off: 'No thinking',
      none: 'No thinking',
      low: 'Low thinking',
      medium: 'Medium thinking',
      high: 'High thinking',
      xhigh: 'Max thinking',
      max: 'Max thinking',
      auto: 'Auto thinking',
    };
    return map[e] || (e.charAt(0).toUpperCase() + e.slice(1) + ' thinking');
  };

  const fmtTok = (n) => {
    const v = Number(n || 0);
    if (!v) return '';
    if (v >= 1e6) return (v / 1e6).toFixed(2) + 'M tok';
    if (v >= 1e3) return (v / 1e3).toFixed(1) + 'K tok';
    return v + ' tok';
  };

  const formatLine = (u) => {
    if (!u) return '';
    const mod = fmtModel(u.resolvedModel || u.resolved_model_id || '');
    const tier = fmtTier(u.tier || u.model || '');
    if (!mod && !tier) return '';
    const effortRaw = u.thinkingEffort || u.thinking_effort || u.effort || readThinkingEffort(u.tier || u.model);
    const effort = fmtEffort(effortRaw);
    const parts = [];
    parts.push('Generated by ' + (mod || tier));
    if (effort) parts.push(effort);
    if (mod && tier) parts.push(tier);
    const ctxPct = Number(u.contextPercent ?? u.context_percent ?? 0);
    if (ctxPct > 0) parts.push('上下文 ' + ctxPct + '%');
    const tok = fmtTok(u.totalTokens ?? u.total_tokens ?? 0);
    if (tok) parts.push(tok);
    return parts.join(' · ');
  };

  // 1. 样式（贴合 AWS Quick 暗/亮双主题的极简灰色小字）
  let css = document.getElementById('qm-model-badge-css');
  if (!css) {
    css = document.createElement('style');
    css.id = 'qm-model-badge-css';
    document.head.appendChild(css);
  }
  css.textContent = \`
    .qm-model-line {
      font-size: 12px;
      line-height: 1.4;
      color: rgba(161, 168, 184, 0.78);
      margin: 6px 0 4px 0;
      user-select: text;
      letter-spacing: 0.01em;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei UI", sans-serif;
    }
    .qm-model-pill-fallback {
      position: fixed;
      right: 16px;
      bottom: 12px;
      z-index: 2147483000;
      font-size: 11.5px;
      color: rgba(203, 213, 225, 0.85);
      background: rgba(18, 20, 26, 0.88);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 999px;
      padding: 4px 11px;
      backdrop-filter: blur(8px);
      pointer-events: none;
    }
  \`;

  // 2. 轻量监听 WebSocket 出站 user_message（抓取本轮思考强度）与入站 turn_usage 帧
  const fromB64 = (s) => {
    const bin = atob(s);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return new TextDecoder().decode(arr);
  };

  const trackOut = (d) => {
    try {
      let txt = '';
      if (typeof d === 'string') txt = d;
      else if (d instanceof ArrayBuffer) txt = new TextDecoder().decode(new Uint8Array(d));
      else if (d && d.buffer) txt = new TextDecoder().decode(new Uint8Array(d.buffer, d.byteOffset || 0, d.byteLength || d.buffer.byteLength));
      if (!txt) return;
      let inner = null;
      if (txt.includes('rawInputEvent')) {
        const outer = JSON.parse(txt);
        if (outer && outer.payload && outer.payload.payload) {
          inner = JSON.parse(fromB64(outer.payload.payload));
        }
      } else if (txt.includes('"user_message"')) {
        inner = JSON.parse(txt);
      }
      if (inner && inner.type === 'user_message' && inner.payload) {
        const p = inner.payload;
        window.__qmTurnDidThink = false;
        window.__qmLastTurnUsage = null;
        const eff = p.thinking_effort || p.thinkingEffort || p.reasoning_effort || p.effort || p.thinking_level || '';
        if (eff) window.__qmLastSentEffort = String(eff).toLowerCase();
        else if (p.thinking_enabled === false || p.thinkingEnabled === false) window.__qmLastSentEffort = 'off';
        else window.__qmLastSentEffort = readThinkingEffort(p.model || p.agent_mode || '');
      }
    } catch (_) {}
  };

  const trackObj = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    if (obj.type === 'thinking_delta' || obj.type === 'thinking_complete' || obj.type === 'thinking_start') {
      window.__qmTurnDidThink = true;
      return;
    }
    if (obj.type === 'turn_usage' && obj.payload) {
      const p = obj.payload;
      const tier = p.model || '';
      const eff = p.thinking_effort || p.thinkingEffort || p.reasoning_effort || p.effort || window.__qmLastSentEffort || readThinkingEffort(tier);
      const rec = {
        ts: Date.now(),
        resolvedModel: p.served_model_id || p.resolved_model_id || p.resolvedModelId || '',
        tier,
        thinkingEffort: eff,
        didThink: !!window.__qmTurnDidThink,
        totalTokens: p.total_tokens || 0,
        contextPercent: p.context_percent || (p.context_window ? Math.round((p.total_tokens || 0) * 1000 / p.context_window) / 10 : 0),
        costUsd: p.cost_usd || 0,
      };
      if (rec.resolvedModel || rec.tier) {
        window.__qmLastTurnUsage = rec;
        window.__qmUsageLog.push(rec);
        if (window.__qmUsageLog.length > 200) window.__qmUsageLog.shift();
        scheduleDecorate();
      }
      return;
    }
    if ((obj.type === 'message_complete' || obj.type === 'text_complete') && obj.payload && obj.payload.text && window.__qmLastTurnUsage) {
      try {
        const rec = Object.assign({}, window.__qmLastTurnUsage, { didThink: !!window.__qmTurnDidThink });
        const k = normKey(obj.payload.text);
        if (k.length >= 4) window.__qmUsageByText[k] = rec;
        scheduleDecorate();
      } catch (_) {}
    }
  };

  // 热升级时静默旧版 v2-v5 钩子，改用独立 v6 回调，确保热注入零重复且支持明文/二进制双帧
  window.__qmOnWsSend = null;
  window.__qmOnWsObj = null;
  window.__qmOnWsSendV6 = trackOut;
  window.__qmOnWsMsgV6 = (ev) => {
    const handleBuf = (ab) => {
      try {
        const txt = new TextDecoder().decode(new Uint8Array(ab));
        const m = txt.match(/\\{"payload":"([A-Za-z0-9+/=]+)"\\}/);
        if (m) trackObj(JSON.parse(fromB64(m[1])));
      } catch (_) {}
    };
    const d = ev.data;
    if (d instanceof ArrayBuffer) handleBuf(d);
    else if (d && typeof d.arrayBuffer === 'function') d.arrayBuffer().then(handleBuf).catch(() => {});
    else if (typeof d === 'string' && d.startsWith('{')) {
      try {
        const parsed = JSON.parse(d);
        if (parsed && parsed.payload && typeof parsed.payload.payload === 'string') {
          try { trackObj(JSON.parse(fromB64(parsed.payload.payload))); return; } catch (_) {}
        }
        if (parsed && parsed.type) trackObj(parsed);
      } catch (_) {}
    }
  };

  const P = WebSocket.prototype;
  if (!P.__qmWrappedV6) {
    const prevSend = P.send;
    P.__qmWrappedV6 = true;
    const hooked = new WeakSet();
    P.send = function (data) {
      try {
        if (window.__qmOnWsSendV6) window.__qmOnWsSendV6(data);
        if (!hooked.has(this)) {
          hooked.add(this);
          this.addEventListener('message', (ev) => {
            try { if (window.__qmOnWsMsgV6) window.__qmOnWsMsgV6(ev); } catch (_) {}
          });
        }
      } catch (_) {}
      return prevSend.apply(this, arguments);
    };
  }

  // 供外部回填历史消息的模型映射（按文本前缀匹配）
  window.__qmPushUsageMap = (entries) => {
    if (!Array.isArray(entries)) return 0;
    let added = 0;
    for (const e of entries) {
      if (!e || !e.prefix || !e.usage) continue;
      if (!window.__qmUsageByText[e.prefix]) {
        window.__qmUsageByText[e.prefix] = e.usage;
        added++;
      }
    }
    scheduleDecorate();
    return added;
  };

  // 精确匹配 AWS Quick AI 回复操作栏（.message-action-bar），绝不误标用户气泡
  const normKey = (t) => String(t || '').replace(/Generated by [^\\n]*/g, '').replace(/\\s+/g, ' ').trim().slice(0, 60);

  const findUsageForBlock = (blockEl, idx, total) => {
    const txt = normKey(blockEl.innerText || '');
    if (txt) {
      if (window.__qmUsageByText[txt]) return window.__qmUsageByText[txt];
      for (const k of Object.keys(window.__qmUsageByText)) {
        if (k.length >= 6 && (txt.includes(k) || k.includes(txt))) return window.__qmUsageByText[k];
      }
    }
    const log = window.__qmUsageLog || [];
    if (log.length && idx === total - 1) return log[log.length - 1];
    return null;
  };

  let decTimer = null;
  const decorate = () => {
    try {
      // 清理旧版可能误插到用户气泡上的节点
      document.querySelectorAll('.qm-model-line').forEach((el) => {
        const next = el.nextElementSibling;
        if (!next || !next.classList.contains('message-action-bar')) el.remove();
      });

      const bars = Array.from(document.querySelectorAll('.message-action-bar'))
        .filter((b) => b.offsetParent !== null && !b.closest('nav, aside, form'));

      let decorated = 0;
      bars.forEach((bar, idx) => {
        const msgContainer = bar.closest('.message-content-col') || bar.parentElement || bar;
        const u = findUsageForBlock(msgContainer, idx, bars.length);
        const lineText = formatLine(u);
        let el = bar.previousElementSibling;
        if (el && !el.classList.contains('qm-model-line')) el = null;
        if (!lineText) return;
        if (!el) {
          el = document.createElement('div');
          el.className = 'qm-model-line';
          bar.parentElement.insertBefore(el, bar);
        }
        if (el.textContent !== lineText) el.textContent = lineText;
        const tipParts = [];
        if (u.resolvedModel) tipParts.push('服务模型: ' + u.resolvedModel);
        const effTip = u.thinkingEffort || readThinkingEffort(u.tier || u.model);
        if (effTip) tipParts.push('请求思考强度: ' + effTip + (u.didThink ? ' (服务端已触发思考)' : ''));
        if (u.costUsd) tipParts.push('估算 $' + Number(u.costUsd).toFixed(4));
        el.title = tipParts.join(' · ');
        decorated++;
      });

      const latest = (window.__qmUsageLog && window.__qmUsageLog[window.__qmUsageLog.length - 1]) || null;
      let fb = document.getElementById('qm-model-fallback');
      if (!decorated && latest) {
        if (!fb) {
          fb = document.createElement('div');
          fb.id = 'qm-model-fallback';
          fb.className = 'qm-model-pill-fallback';
          document.body.appendChild(fb);
        }
        fb.textContent = formatLine(latest);
      } else if (fb) {
        fb.remove();
      }
    } catch (_) {}
  };

  const scheduleDecorate = () => {
    clearTimeout(decTimer);
    decTimer = setTimeout(decorate, 180);
  };

  if (window.__qmObserver) {
    try { window.__qmObserver.disconnect(); } catch (_) {}
  }
  window.__qmObserver = new MutationObserver(scheduleDecorate);
  window.__qmObserver.observe(document.body, { childList: true, subtree: true });
  scheduleDecorate();

  window.__qmInspectDom = () => {
    const lines = Array.from(document.querySelectorAll('.qm-model-line')).map((e) => e.textContent);
    return {
      ver: VER,
      url: location.href,
      title: document.title,
      actionBars: document.querySelectorAll('.message-action-bar').length,
      decoratedLines: lines,
      currentEffort: readThinkingEffort(''),
      liveUsageCount: (window.__qmUsageLog || []).length,
      textMapCount: Object.keys(window.__qmUsageByText || {}).length,
    };
  };

  return { ok: true, status: 'attached', ver: VER, currentEffort: readThinkingEffort('') };
})()`;

async function attachAndSync(usageEntries = []) {
  try {
    const target = await findPageTarget(CDP_PORT);
    if (!target) {
      state = { ...state, reachable: false, attached: false, lastError: '未检测到 9222 调试端口（需带 --remote-debugging-port=9222 启动 AWS Quick）' };
      return { ok: false, ...state };
    }
    const res = await evalInPage(target.webSocketDebuggerUrl, BADGE_SCRIPT);
    let pushed = 0;
    if (Array.isArray(usageEntries) && usageEntries.length) {
      pushed = await evalInPage(
        target.webSocketDebuggerUrl,
        `window.__qmPushUsageMap ? window.__qmPushUsageMap(${JSON.stringify(usageEntries)}) : 0`
      ).catch(() => 0);
    }
    state = {
      ...state,
      reachable: true,
      attached: !!(res && res.ok),
      targetTitle: target.title || '',
      targetUrl: target.url || '',
      lastAttachAt: Date.now(),
      lastError: null,
    };
    return { ok: true, ...state, pushed, evalResult: res };
  } catch (e) {
    state = { ...state, reachable: false, attached: false, lastError: (e && e.message) || String(e) };
    return { ok: false, ...state };
  }
}

async function inspectDom() {
  const target = await findPageTarget(CDP_PORT);
  if (!target) return { ok: false, error: '未检测到 9222 调试端口' };
  await evalInPage(target.webSocketDebuggerUrl, BADGE_SCRIPT);
  const info = await evalInPage(target.webSocketDebuggerUrl, 'window.__qmInspectDom ? window.__qmInspectDom() : null');
  state.lastInspect = info;
  return { ok: true, target: { title: target.title, url: target.url }, info };
}

function getStatus() {
  return { ...state };
}

module.exports = {
  CDP_PORT,
  getStatus,
  findPageTarget,
  attachAndSync,
  inspectDom,
};
